      p5.Vector.dist(this.leftTopPoint, this.rightTopPoint) * 0.3;
    this.topHeight =
      p5.Vector.dist(this.leftTopPoint, this.rightTopPoint) * 0.1;
    this.leftEarParams = argus.leftEarParams || {
      width: 0.3,
      height: 1,
      leftSide: {
        ratio: 0.3,
        amp: 1,
        sShape: false,
      },
      rightSide: {
        ratio: 0.3,
        amp: 1,
        sShape: false,
      },
    };
    this.rightEarParams = argus.rightEarParams || {
      width: 0.3,
      height: 1,
      leftSide: {
        ratio: 0.3,
        amp: 1,
        sShape: false,
      },
      rightSide: {
        ratio: 0.3,
        amp: 1.3,
        sShape: false,
      },
    };
    this.topHeadParams = argus.topHeadParams || {
      ratio: 0.3,
      amp: 1.3,
    };
    this.rightFaceParams = argus.rightFaceParams || {
      ratio: 0.3,
      amp: 1.5,
    };
    this.eyeSize = argus.eyeSize;
    this.contourColor = argus.contourColor;
    this.leftEyeColor = argus.leftEyeColor;
    this.rightEyeColor = argus.rightEyeColor;
    this.updateContour();
  }

  updateContour() {
    //left ear
    this.leftEarPoint = [];
    this.leftEarPoint[0] = this.leftTopPoint;
    this.leftEarPoint[1] = p5.Vector.lerp(
      this.leftTopPoint,
      this.rightTopPoint,
      this.leftEarParams.width / 2
    ).add(0, -this.earHeight * this.leftEarParams.height);
    this.leftEarPoint[2] = p5.Vector.lerp(
      this.leftTopPoint,
      this.rightTopPoint,
      this.leftEarParams.width
    ).add(0, -this.topHeight);
