function getCtrlPoints(p1, p2, ratio, amp, sShape) {
  let result = [];
  const offSet = p5.Vector.sub(p2, p1)
    .rotate(-PI / 2)
    .mult(0.1 * amp);
  if (sShape) {
    result[0] = p5.Vector.lerp(p1, p2, ratio).add(offSet);
    result[1] = p5.Vector.lerp(p1, p2, 1 - ratio).sub(offSet);
  } else {
    result[0] = p5.Vector.lerp(p1, p2, ratio).add(offSet);
    result[1] = p5.Vector.lerp(p1, p2, 1 - ratio).add(offSet);
  }
  return result;
}

function easeInOutSine(x) {
	return -(Math.cos(Math.PI * x) - 1) / 2;
}


function easeOutCubic(x) {
return 1 - Math.pow(1 - x, 3);
}

